import { TreeDataNode } from '../types';
import { DataEntity, Value } from './interface';

function traverseDataNodes(
  dataNodes: TreeDataNode[],
  callback: (data: {
    node: TreeDataNode;
    index: number;
    pos: string;
    key: Value;
    parentPos: string;
    level: number;
    nodes: TreeDataNode[];
  }) => void,
) {
  function processNode(
    node: TreeDataNode | null,
    index?: number,
    parent?: { node: TreeDataNode; pos: string; level: number },
    pathNodes?: TreeDataNode[],
  ) {
    const children = node ? node.children : dataNodes;
    const pos = node ? `${parent!.pos}-${index}` : '0';
    const connectedNodes = node ? [...(pathNodes || []), node] : [];
    const key = node ? node.value : '__root__';

    if (node) {
      const data = {
        node,
        index: index || 0,
        pos,
        key,
        parentPos: parent?.pos || '',
        level: (parent?.level || 0) + 1,
        nodes: connectedNodes,
      };
      callback(data);
    }

    // Recursively process children
    if (children) {
      children.forEach((child, childIndex) => {
        processNode(
          child,
          childIndex,
          {
            node: node as TreeDataNode,
            pos,
            level: parent ? parent.level + 1 : -1,
          },
          connectedNodes,
        );
      });
    }
  }

  processNode(null);
}

interface Entities {
  posEntities: Record<string, DataEntity>;
  keyEntities: Record<Value, DataEntity>;
}

/** Convert `treeData` into entity records. */
export function convertDataToEntities<E extends Entities = Entities>(
  dataNodes: TreeDataNode[],
  {
    initEntities,
    processEntity,
  }: {
    initEntities?: (entities: E) => E;
    processEntity?: (entity: DataEntity, entities: E) => void;
  } = {},
) {
  const posEntities: Record<string, DataEntity> = {};
  const keyEntities: Record<Value, DataEntity> = {};
  const entities = initEntities?.({ posEntities, keyEntities } as E) || ({ posEntities, keyEntities } as E);

  traverseDataNodes(dataNodes, (item) => {
    const { node, index, pos, key, parentPos, level, nodes } = item;
    const entity: DataEntity = { node, nodes, index, pos, key, level };

    posEntities[pos] = entity;
    keyEntities[key] = entity;

    entity.parent = posEntities[parentPos];
    if (entity.parent) {
      entity.parent.children = entity.parent.children || [];
      entity.parent.children.push(entity);
    }

    if (processEntity) {
      processEntity(entity, entities as E);
    }
  });
  return entities;
}
